// One-off dev tool: merges the existing authoring catalog
// (public/no-line/constellation-anchors.json — constellationId/artImage/
// artBounds plus the full list of every star each constellation's line
// figure references, from the `unmapped` field) with Task 1's machine-exact
// skeleton coordinates (tmp/constellation-captures/skeleton-coordinates.json,
// generated by capture-all-constellations.mjs from the live app's own
// screen-projection math) into a single draft placement file.
//
// Each star gets `skeletonPixel` (normalized 0-1, from Task 1) when the
// capture run had it above the horizon, or null when it didn't (some
// constellations' full star lists aren't all above the horizon at once —
// see docs/features/phase-13-implementation-tasks.md Task 4). `artPixel` is
// always null here — deciding where each star's motif sits in the no-line
// illustration is Task 3, not this merge.
//
// Usage: node scripts/build-constellation-art-placement-draft.mjs
import { readFile, writeFile } from 'node:fs/promises'
import path from 'node:path'

const ROOT = path.resolve(import.meta.dirname, '..')
const ANCHORS_PATH = path.join(ROOT, 'public/no-line/constellation-anchors.json')
const SKELETON_PATH = path.join(
  ROOT,
  'tmp/constellation-captures/skeleton-coordinates.json',
)
const OUTPUT_PATH = path.join(
  ROOT,
  'tmp/constellation-captures/constellation-art-placement-draft.json',
)

async function main() {
  const anchors = JSON.parse(await readFile(ANCHORS_PATH, 'utf-8'))
  const skeleton = JSON.parse(await readFile(SKELETON_PATH, 'utf-8'))

  const skeletonByConstellation = new Map(
    skeleton.constellations.map((c) => [c.constellationId, c]),
  )

  const constellations = anchors.constellations.map((entry) => {
    const skeletonEntry = skeletonByConstellation.get(entry.constellationId)
    if (skeletonEntry === undefined) {
      throw new Error(`No skeleton capture found for ${entry.constellationId}`)
    }
    const skeletonByStarId = new Map(
      skeletonEntry.anchors.map((a) => [a.starId, a]),
    )

    const stars = entry.unmapped.map(({ starId }) => {
      const captured = skeletonByStarId.get(starId)
      return {
        starId,
        properName: captured?.properName ?? null,
        skeletonPixel:
          captured === undefined
            ? null
            : { x: captured.xPercent / 100, y: captured.yPercent / 100 },
        artPixel: null,
        note:
          captured === undefined
            ? '直近のキャプチャ実行時点で地平線下だったため骨格座標なし'
            : null,
      }
    })

    return {
      constellationId: entry.constellationId,
      constellationNameJa: skeletonEntry.constellationNameJa,
      artImage: entry.image,
      artBounds: entry.artBounds,
      stars,
    }
  })

  await writeFile(
    OUTPUT_PATH,
    `${JSON.stringify({ version: 1, constellations }, null, 2)}\n`,
  )

  const totalStars = constellations.reduce((sum, c) => sum + c.stars.length, 0)
  const withSkeleton = constellations.reduce(
    (sum, c) => sum + c.stars.filter((s) => s.skeletonPixel !== null).length,
    0,
  )
  console.log(
    `Wrote ${constellations.length} constellation(s), ${totalStars} star(s) (${withSkeleton} with skeletonPixel) to ${path.relative(ROOT, OUTPUT_PATH)}`,
  )
}

main().catch((err) => {
  console.error(err)
  process.exit(1)
})
